<?php
namespace Tests\Feature;
use App\Models\{User,Customer,SalesInvoice}; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class PaymentManagementTest extends TestCase { use RefreshDatabase; public function test_payment_rejects_overpayment_and_marks_invoice_paid(): void { $user=User::factory()->create(['role'=>'admin']);$customer=Customer::create(['name'=>'Test']);$invoice=SalesInvoice::create(['invoice_number'=>'S-1','customer_id'=>$customer->id,'issue_date'=>now(),'due_date'=>now()->addDay(),'total'=>'100']);$payload=['payment_date'=>now()->toDateString(),'method'=>'cash'];$this->actingAs($user)->post(route('invoices.payments.store',['sales',$invoice]),array_merge($payload,['amount'=>101]))->assertSessionHasErrors('amount');$this->actingAs($user)->post(route('invoices.payments.store',['sales',$invoice]),array_merge($payload,['amount'=>100]))->assertSessionHas('success');$this->assertSame('Paid',$invoice->fresh()->status);$this->assertDatabaseHas('payments',['invoice_id'=>$invoice->id,'amount'=>'100.00']);} }
